{
  "correction_rules": [
    "Adjust forecasts downward when model shows persistent overestimation in early days of the 30-day horizon, especially after recent price spikes.",
    "Apply a mild upward bias correction if sentiment remains neutral or slightly positive, as models tend to underreact to bullish sentiment.",
    "Reduce forecast volatility in the final 5–7 days of the 30-day horizon to avoid overshoots following sharp price increases.",
    "Incorporate mean reversion logic: if forecast exceeds 2 standard deviations above recent 10-day average, reduce by 10–15%.",
    "If sentiment history is flat (all 0.00), apply a conservative correction: subtract 1–2% from forecasted values to account for model overconfidence.",
    "Avoid overreacting to short-term volatility: if true outcome shows a sharp drop after a spike, model should not follow with a similar drop — instead, smooth the transition."
  ]
}
